function seed(){return {me:'c0',companies:names.map((name,i)=>({id:'c'+i,name,city:cities[i],team:[4,6,3,7][i],cv:['Отделка офисных помещений','Реставрация фасадов','Интерьеры квартир','Коммерческая отделка'][i],experience:['Haven Bouw','Atelier Oost','Wonen Noord','Bureau West'][i],proof:'demo',gallery:[],demo:true})),jobs:['Покраска офиса у канала','Отделка жилого комплекса','Обновление фасада','Покраска шоурума','Реставрация окон','Отделка мастерской'].map((title,i)=>({id:'j'+i,title,city:cities[i],owner:'c'+[1,2,0,3,1,2][i],status:['open','open','booked','open','open','done'][i],price:[3400,5850,4200,2700,3200,1900][i],team:[3,5,4,2,3,2][i],start:day([3,5,2,7,10,-8][i]),end:day([8,14,12,10,16,-2][i]),area:[180,420,240,145,95,110][i],desc:['Подготовка стен и покраска офисных помещений в два слоя. Материалы на объекте.','Финишная отделка стен и потолков в новых квартирах.','Подготовка и покраска уличного фасада.','Стены и деревянные панели торгового зала.','Подготовка рам и нанесение защитного покрытия.','Внутренняя отделка стен мастерской.'][i],offers:i===2||i===5?[{by:'c3',price:i===2?4200:1900,note:'Готовы выполнить заказ.'}]:[],accepted:i===2||i===5?'c3':null}))}}
let st;try{st=JSON.parse(localStorage.getItem(key));if(!st?.companies||!st.jobs||!st.companies.some(c=>c.id===st.me))st=seed()}catch{st=seed()}
let page='jobs',filter='all',mode='map',toastTimer;const company=id=>st.companies.find(c=>c.id===id), job=id=>st.jobs.find(j=>j.id===id), me=()=>company(st.me), initial=n=>n.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase(), avatar=c=>c.portrait?'<img class="avatar" alt="" src="'+esc(c.portrait)+'">':'<span class="avatar">'+esc(initial(c.name))+'</span>';
