const act=(name,id='',label='',cls='')=>'<button class="'+cls+'" data-action="'+name+'" data-id="'+esc(id)+'">'+label+'</button>';
function nav(){return Object.entries(pages).map(([k,v])=>'<button class="navbtn '+(page===k?'active':'')+'" data-page="'+k+'">'+icon(k)+'<span>'+v+'</span></button>').join('')}
