function render(){const n=nav();$('nav').innerHTML=n;$('.mobileNav').innerHTML=n;$('#account').innerHTML=avatar(me())+'<span class="accountName">'+esc(me().name)+'</span>'+icon('down');$('#crumb').textContent=pages[page];$('#heading').textContent=intro[page][0];$('#sub').textContent=intro[page][1];$('.publish').innerHTML=icon('plus')+'Разместить объект';const v=$('#view');if(page==='orgs'){v.innerHTML='<div class="directory">'+st.companies.map(c=>'<button class="panel org" data-action="profile" data-id="'+c.id+'">'+avatar(c)+'<h3>'+esc(c.name)+'</h3><div class="meta">'+icon('pin')+esc(city(c.city))+' · '+c.team+' чел.</div><p class="muted">'+esc(c.cv)+'</p></button>').join('')+'</div>';return}
if(page==='deals'){const own=st.jobs.filter(j=>j.owner===st.me),mine=st.jobs.filter(j=>j.offers.some(o=>o.by===st.me));v.innerHTML='<h2>Мои объекты</h2><div class="directory mt">'+cards(own)+'</div><h2 class="mt">Мои отклики</h2><div class="directory mt">'+cards(mine)+'</div>';return}
const js=st.jobs.filter(j=>filter==='all'||j.status===filter);
v.innerHTML='<div class="stats">'+[[st.jobs.filter(j=>j.status==='open').length,'Открытые объекты','jobs'],[st.jobs.filter(j=>j.status==='booked').length,'Забронированы','calendar'],[st.companies.length,'Компании','users']].map(([n,l,i],k)=>'<div class="stat"><span class="statIcon a'+k+'">'+icon(i)+'</span><div><strong>'+n+'</strong><small>'+l+'</small></div></div>').join('')+'</div><div class="mobileTabs">'+act('mode','map','Карта','chip '+(mode==='map'?'active':''))+act('mode','list','Список','chip '+(mode==='list'?'active':''))+'</div><div class="board mode-'+mode+'"><section class="panel mapPanel"><div class="panelHead"><h2>Карта объектов</h2><span class="caption">Нидерланды</span></div><div id="map" class="mapbox"></div><div class="legend"><span><i class="dot"></i>Открыт</span><span><i class="dot purple"></i>Забронирован</span><span><i class="dot grey"></i>Завершён</span></div></section><section class="panel listPanel"><div class="panelHead"><h2>Объекты</h2><span class="caption">'+js.length+' из '+st.jobs.length+'</span></div><div class="filter">'+[['all','Все'],['open','Открытые'],['booked','Бронь'],['done','Завершены']].map(([k,v])=>act('filter',k,v,'chip '+(k===filter?'active':''))).join('')+'</div><div class="cards">'+cards(js)+'</div></section></div>';if(window.KwastMap)KwastMap.render($('#map'),js,id=>showJob(String(id)),null)}
const dlg=$('#dialog');function modal(tag,html){$('#modalTag').textContent=tag;$('#modal').innerHTML=html;if(!dlg.open)dlg.showModal();dlg.scrollTop=0}
$('#close').onclick=()=>dlg.close();dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close()}});
function settle(by,amt){const fee=Math.round(amt*8)/100;return '<div class="note">Стоимость '+price(amt)+' · Комиссия 8%: '+price(fee)+' · Исполнителю: '+price(amt-fee)+'. Демо-расчёт без списания денег.</div>'}
function available(j,by,limit=company(by)?.team){
 const crew=company(by);if(!crew||j.team>limit)return false;
 const shifts=new Map();
 for(const other of st.jobs){
  if(other.id===j.id||other.status!=='booked'||other.accepted!==by||other.start>j.end||other.end<j.start)continue;
  const first=Math.max(Date.parse(j.start),Date.parse(other.start)),after=Math.min(Date.parse(j.end),Date.parse(other.end))+86400000;
  shifts.set(first,(shifts.get(first)||0)+other.team);shifts.set(after,(shifts.get(after)||0)-other.team);
 }
 let used=j.team;
 for(const t of [...shifts.keys()].sort((a,b)=>a-b)){used+=shifts.get(t);if(used>limit)return false}
 return true
}
function cancelBooking(j,commit){
 if(!j||j.status!=='booked'||(j.owner!==st.me&&j.accepted!==st.me))return;
 if(!commit){modal('БРОНИРОВАНИЕ','<h2>Отменить бронь?</h2><p>Объект снова откроется для предложений. Бригада освободится на эти даты.</p><div class="actions">'+act('doCancel',j.id,'Отменить бронь')+act('job',j.id,'Сохранить бронь','primary')+'</div>');return}
 if(save(()=>{j.offers=j.offers.filter(o=>o.by!==j.accepted);j.accepted=null;j.status='open'})){render();showJob(j.id);toast('Бронь отменена')}
}
function showJob(id){let j=job(id);if(!j)return;const own=j.owner===st.me,accepted=j.offers.find(o=>o.by===j.accepted),my=j.offers.find(o=>o.by===st.me);let actions='';if(own&&j.status==='open'){actions='<h3>Предложения бригад</h3>'+(j.offers.map(o=>'<div class="offer"><div class="flex">'+act('profile',o.by,esc(company(o.by).name),'textbtn')+'<b>'+price(o.price)+'</b></div><p>'+esc(o.note)+'</p>'+settle(o.by,o.price)+act('book',id+'|'+o.by,'Забронировать бригаду','primary')+'</div>').join('')||'<p class="muted">Откликов пока нет.</p>')}
if(!own&&j.status==='open')actions=my?'<div class="info">Ваше предложение: <b>'+price(my.price)+'</b></div>':act('offer',id,'Предложить бригаду','primary');
if(accepted)actions='<h3>Исполнитель</h3>'+act('profile',accepted.by,esc(company(accepted.by).name),'textbtn')+((own||accepted.by===st.me)?settle(accepted.by,accepted.price):'')+(own&&j.status==='booked'?'<div class="actions">'+act('finish',id,'Подтвердить завершение','primary')+'</div>':'');
if(j.status==='booked'&&(own||j.accepted===st.me))actions+='<div class="actions">'+act('cancelBooking',id,'Отменить бронь')+'</div>';
modal('КАРТОЧКА ОБЪЕКТА','<span class="pill '+j.status+'">'+labels[j.status]+'</span><h2>'+esc(j.title)+'</h2><div class="meta">'+icon('pin')+esc(city(j.city))+' · '+date(j.start)+' – '+date(j.end)+'</div><div class="info"><b>'+price(j.price)+'</b> · '+j.team+' чел. · '+j.area+' м²</div><p>'+esc(j.desc)+'</p><h3>Заказчик</h3>'+act('profile',j.owner,esc(company(j.owner).name),'textbtn')+'<div class="mt">'+actions+'</div>')}
function profile(id){const c=company(id);if(!c)return;modal('ПРОФИЛЬ КОМПАНИИ','<div class="split">'+avatar(c)+'<h2>'+esc(c.name)+'</h2></div><p class="meta">'+icon('pin')+esc(city(c.city))+' · '+c.team+' чел.'+(c.demo?' · Демо-компания':'')+'</p><h3>О команде</h3><p>'+esc(c.cv||'Описание пока не добавлено.')+'</p><h3>Опыт работы</h3><p>'+esc(c.experience||'Компании пока не указаны.')+'</p>'+(c.proof==='demo'?'<span class="label">✓ Подтверждено · пример</span>':c.proof==='pending'?'<span class="pill booked">Ожидает проверки · демо</span>':'')+'<h3>Портфолио</h3>'+(c.gallery?.length?'<div class="gallery">'+c.gallery.map(s=>'<img src="'+esc(s)+'" alt="Работа компании">').join('')+'</div>':'<p class="muted">Фотографии пока не добавлены.</p>')+(id===st.me?'<div class="actions">'+act('editProfile',id,'Изменить профиль')+'</div>':''))}
function accounts(){modal('ДЕМО-КАБИНЕТ','<h2>Сменить компанию</h2><p class="note">Переключайтесь между участниками, чтобы проверить обе стороны сделки. Данные сохраняются только на этом устройстве.</p>'+st.companies.map(c=>'<button class="switch '+(st.me===c.id?'active':'')+'" data-action="switch" data-id="'+c.id+'">'+avatar(c)+'<span>'+esc(c.name)+'<br><small>'+(st.me===c.id?'Текущая компания':esc(city(c.city)))+'</small></span></button>').join('')+'<div class="actions">'+act('newProfile','','Зарегистрировать компанию','primary')+act('profile',st.me,'Мой профиль')+'</div>')}
$('#account').onclick=accounts;
const field=(l,input)=>'<label>'+l+input+'</label>', inp=(n,v='',extra='')=>'<input name="'+n+'" value="'+esc(v)+'" '+extra+'>', opts=(v='')=>'<select name="city">'+cities.map((c,i)=>'<option value="'+c+'" '+(c===v?'selected':'')+'>'+cityNames[i]+'</option>').join('')+'</select>';
function form(tag,title,body,submit){modal(tag,'<h2>'+title+'</h2><form class="fields" id="entry">'+body+'<div class="formerr" role="alert"></div><button type="submit" class="primary">'+submit+'</button></form>')}
function onSubmit(fn){$('#entry').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;try{await fn(Object.fromEntries(new FormData(f)),f)}catch(er){f.querySelector('.formerr').textContent=er.message||'Не удалось сохранить.'}finally{button.disabled=false}}}
function publish(){form('НОВЫЙ ОБЪЕКТ','Разместить объект',field('Название',inp('title','','required maxlength="85" placeholder="Например, покраска офиса"'))+field('Город',opts())+'<div class="cols">'+field('Начало',inp('start',day(1),'type="date" min="'+day(0)+'" required'))+field('Завершение',inp('end',day(5),'type="date" required'))+'</div><div class="cols">'+field('Площадь, м²',inp('area','','type="number" min="1" max="999999" required'))+field('Нужно маляров',inp('team',2,'type="number" min="1" max="200" required'))+'</div>'+field('Бюджет, €',inp('price','','type="number" min="1" max="10000000" step=".01" required'))+field('Описание работ','<textarea name="desc" required maxlength="1800"></textarea>'),'Опубликовать');onSubmit(d=>{if(d.end<d.start)throw Error('Дата завершения должна быть не раньше начала.');if(!d.title.trim()||!d.desc.trim())throw Error('Введите название и описание.');const j={...d,title:d.title.trim(),id:uid(),status:'open',owner:st.me,offers:[],accepted:null,team:+d.team,area:+d.area,price:+d.price};if(save(()=>st.jobs.unshift(j))){page='jobs';filter='all';render();showJob(j.id);toast('Объект опубликован в демо')}})}
function offer(id){const j=job(id);if(!j||j.owner===st.me||j.status!=='open')return;if(!available(j,st.me)){toast('Недостаточно свободных маляров на эти даты.');return}form('ОТКЛИК НА ОБЪЕКТ','Предложить бригаду','<p>'+esc(j.title)+'</p>'+field('Стоимость работ, €',inp('amount',j.price,'type="number" min="1" max="10000000" step=".01" required'))+field('Условия предложения','<textarea name="note" maxlength="1000" required placeholder="Когда готовы начать?"></textarea>')+'<div id="total">'+settle(st.me,j.price)+'</div>','Отправить предложение');$('#entry [name=amount]').oninput=e=>$('#total').innerHTML=settle(st.me,Number(e.target.value));onSubmit(d=>{if(!available(j,st.me))throw Error('Недостаточно свободных маляров на эти даты.');if(!d.note.trim())throw Error('Укажите условия предложения.');if(!j.offers.some(o=>o.by===st.me)&&save(()=>j.offers.push({by:st.me,price:+d.amount,note:d.note.trim()}))){render();showJob(id);toast('Предложение отправлено')}})}
function uid(){return 'u'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
async function shrink(f){if(!f?.size)return '';if(f.size>8000000)throw Error('Выберите изображение до 8 МБ.');const u=URL.createObjectURL(f);try{const im=new Image();im.src=u;await im.decode();const scale=Math.min(1,800/Math.max(im.width,im.height)),a=document.createElement('canvas');a.width=Math.max(1,Math.round(im.width*scale));a.height=Math.max(1,Math.round(im.height*scale));a.getContext('2d').drawImage(im,0,0,a.width,a.height);return a.toDataURL('image/jpeg',.68)}finally{URL.revokeObjectURL(u)}}
function profileForm(edit){const c=edit?me():{};form('ПРОФИЛЬ КОМПАНИИ',edit?'Изменить профиль':'Регистрация компании','<p class="note">Тестовый профиль на этом устройстве. Используйте вымышленные реквизиты и учебные документы.</p>'+field('Компания',inp('name',c.name,'required maxlength="65"'))+'<div class="cols">'+field('Город',opts(c.city))+field('Размер бригады',inp('team',c.team||2,'type="number" min="1" max="200" required'))+'</div>'+field('Номер KvK (8 цифр)',inp('kvk',c.kvk,'inputmode="numeric" pattern="[0-9]{8}" maxlength="8" '+(c.demo?'':'required')))+field('О команде / CV','<textarea name="cv" maxlength="1200">'+esc(c.cv)+'</textarea>')+field('Опыт — компания-заказчик',inp('experience',c.experience,'maxlength="100"'))+field('Фото профиля','<input name="portrait" type="file" accept="image/*">')+field('Добавить работы в портфолио (до 4 фото)','<input name="gallery" type="file" multiple accept="image/*">')+field('Учебная фактура для проверки опыта','<input name="proof" type="file" accept=".pdf,image/*">')+'<p class="note">Для фактуры сохраняется только отметка о заявке. Содержимое файла не читается. В пилоте проверку документов имитирует статус «Ожидает проверки».</p>',edit?'Сохранить':'Создать профиль');onSubmit(async(d,f)=>{if(!d.name.trim())throw Error('Введите название компании.');const images=Array.from(f.elements.gallery.files);if(images.length+(c.gallery?.length||0)>4)throw Error('Можно добавить не больше четырёх фото портфолио.');if(d.proof.size&&!d.experience.trim())throw Error('Укажите, к какой компании относится фактура.');const gallery=[...(c.gallery||[]),...await Promise.all(images.map(shrink))],portrait=await shrink(d.portrait)||c.portrait||'',proof=d.proof.size?'pending':c.experience===d.experience?c.proof:null;if(edit&&st.jobs.some(j=>j.status==='booked'&&j.accepted===c.id&&!available(j,c.id,+d.team)))throw Error('Число маляров меньше уже забронированного на эти даты.');const row={...c,id:c.id||uid(),name:d.name.trim(),team:+d.team,city:d.city,cv:d.cv,kvk:d.kvk,experience:d.experience,gallery,portrait,proof};if(save(()=>{if(edit)Object.assign(c,row);else{st.companies.push(row);st.me=row.id}})){render();profile(row.id);toast('Профиль сохранён')}})}
function confirmAction(id,by,finish){const j=job(id),o=j?.offers.find(x=>x.by===(finish?j.accepted:by));if(!o||j.owner!==st.me||j.status!==(finish?'booked':'open'))return;if(!finish&&!available(j,by)){toast('На эти даты у бригады недостаточно свободных маляров.');return}modal('ПОДТВЕРЖДЕНИЕ','<h2>'+(finish?'Завершить работы?':'Забронировать бригаду?')+'</h2><p>'+esc(j.title)+' · '+esc(company(o.by).name)+'</p>'+settle(o.by,o.price)+'<div class="actions">'+act(finish?'doFinish':'doBook',j.id+'|'+o.by,finish?'Завершить':'Подтвердить бронь','primary')+act('job',j.id,'Назад')+'</div>')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-page],[data-action]');if(!el)return;e.preventDefault();if(el.dataset.page){page=el.dataset.page;render();window.scrollTo(0,0);return}const {action:a,id}=el.dataset;if(a==='filter'){filter=id;render()}else if(a==='mode'){mode=id;render()}else if(a==='job')showJob(id);else if(a==='newJob')publish();else if(a==='offer')offer(id);else if(a==='profile')profile(id);else if(a==='editProfile'||a==='newProfile')profileForm(a==='editProfile');else if(a==='switch'&&company(id)){if(save(()=>st.me=id)){dlg.close();render();toast('Кабинет: '+me().name)}}else if(a==='cancelBooking'||a==='doCancel')cancelBooking(job(id),a==='doCancel');else if(a==='book'||a==='finish'){const [jid,by]=id.split('|');confirmAction(jid,by,a==='finish')}else if(a==='doBook'||a==='doFinish'){const [jid,by]=id.split('|'),j=job(jid);if(j?.owner!==st.me||!j.offers.some(o=>o.by===by)||j.status!==(a==='doBook'?'open':'booked')||(a==='doFinish'&&j.accepted!==by))return;if(a==='doBook'&&!available(j,by)){toast('Бригада уже занята в эти даты.');return}if(save(()=>{j.accepted=by;j.status=a==='doBook'?'booked':'done'})){render();showJob(jid);toast(a==='doBook'?'Бригада забронирована':'Работы завершены')}}});
window.addEventListener('storage',e=>{if(e.key!==key||!e.newValue)return;try{const next=JSON.parse(e.newValue);if(next.companies?.length&&Array.isArray(next.jobs)){st=next;if(dlg.open)dlg.close();render()}}catch{}});
